 1	type T = int // for demo purposes, but could be another type
 2	predicate sorted(a: array<T>, n: nat) 
 3	    requires n <= (a.Length) + 1
 4	    reads a
 5	{
 6	    forall i,j :: 0 <= i < j < n ==> a[i] <= a[j]
 7	}
 8	
 9	// Use binary search to find an appropriate position to insert a value 'x'
10	// in a sorted array 'a', so that it remains sorted.
11	method binarySearch(a: array<T>, x: T) returns (index: int) 
12	    requires sorted(a, a.Length)
13	    ensures sorted(a, a.Length)
14	    //ensures a[..] == old(a)[..]
15	    ensures 0 <= index <= a.Length
16	    //ensures forall i :: 0 <= i < index ==> a[i] <= x
17	    //ensures forall i :: index <= i < a.Length ==> a[i] >= x
18	
19	    ensures index > 0 ==> a[index-1] <= x
20	    ensures index < a.Length ==> a[index] >= x
21	{
22	    var low, high := 0, a.Length;
23	    while low < high 
24	        decreases high-low
25	        invariant 0 <= low <= high <= a.Length
26	        invariant low > 0 ==> a[low-1] <= x
27	        invariant high < a.Length ==> a[high] >= x
28	
29	    {
30	        var mid := low + (high - low) / 2;
31	        if {
32	            case a[mid] < x => low := mid + 1;
33	            case a[mid] > x => high := mid;
34	            case a[mid] == x => return mid;
35	        }
36	    }
37	    return low;
38	}
39	
40	// Simple test cases to check the post-condition
41	method testBinarySearch() {
42	    var a := new int[2] [1, 3];
43	    var id0 := binarySearch(a, 0);
44	    assert id0 == 0;
45	    var id1 := binarySearch(a, 1);
46	    assert id1 in {0, 1};
47	    var id2 := binarySearch(a, 2);
48	    assert id2 == 1;
49	    var id3 := binarySearch(a, 3);
50	    assert id3 in {1, 2};
51	    var id4 := binarySearch(a, 4);
52	    assert id4 == 2;
53	}
